from __future__ import annotations

import hashlib
import re
from dataclasses import dataclass

from muclegal.normalize.core import normalize_plain_text


_LEGAL_HEADING = re.compile(
    r"^(?:(?P<section>§+\s*\d+[a-zA-Z]*)|"
    r"(?P<article>Artikel\s+\d+[a-zA-Z]*)|"
    r"(?P<number>\d+(?:\.\d+)*\.(?!\d))|"
    r"(?P<paragraph>\(\d+\))|"
    r"(?P<letter>(?:lit\.\s*)?[a-z]\)))\s*",
    re.IGNORECASE,
)
_SENTENCE_BOUNDARY = re.compile(r"(?<=[.!?])\s+(?=[A-ZÄÖÜ0-9§(])")


@dataclass(frozen=True)
class Clause:
    ordinal: int
    heading_path: str | None
    text: str
    clause_hash: str
    is_tenor_relevant: bool = False


def split_clauses(text: str) -> tuple[Clause, ...]:
    """Split canonical text deterministically, preferring legal structure."""
    canonical = normalize_plain_text(text).rstrip("\n")
    if not canonical:
        return ()
    paragraphs = [line for line in canonical.split("\n") if line]
    if any(_LEGAL_HEADING.match(line) for line in paragraphs):
        chunks = _split_legal(paragraphs)
    else:
        chunks = [(None, part) for paragraph in paragraphs for part in _bounded_blocks(paragraph)]
    return tuple(
        Clause(
            ordinal=index,
            heading_path=heading,
            text=chunk,
            clause_hash=hashlib.sha256(chunk.encode("utf-8")).hexdigest(),
        )
        for index, (heading, chunk) in enumerate(chunks, start=1)
        if chunk
    )


def _split_legal(paragraphs: list[str]) -> list[tuple[str | None, str]]:
    chunks: list[tuple[str | None, str]] = []
    hierarchy: list[str] = []
    current_heading: str | None = None
    buffer: list[str] = []

    def flush() -> None:
        if not buffer:
            return
        combined = "\n".join(buffer)
        chunks.extend((current_heading, part) for part in _bounded_blocks(combined))
        buffer.clear()

    for paragraph in paragraphs:
        match = _LEGAL_HEADING.match(paragraph)
        if match:
            flush()
            marker = match.group(0).strip()
            level = _heading_level(match)
            hierarchy[level:] = []
            if len(hierarchy) < level:
                hierarchy.extend([""] * (level - len(hierarchy)))
            hierarchy.append(marker)
            current_heading = " > ".join(item for item in hierarchy if item)
        buffer.append(paragraph)
    flush()
    return chunks


def _heading_level(match: re.Match[str]) -> int:
    if match.group("section") or match.group("article"):
        return 0
    if match.group("number"):
        return match.group("number").count(".") - 1
    if match.group("paragraph"):
        return 1
    return 2


def _bounded_blocks(value: str, minimum: int = 400, maximum: int = 800) -> list[str]:
    if len(value) <= maximum:
        return [value]
    sentences = _SENTENCE_BOUNDARY.split(value.replace("\n", " "))
    blocks: list[str] = []
    current = ""
    for sentence in sentences:
        if len(sentence) > maximum:
            if current:
                blocks.append(current)
                current = ""
            blocks.extend(sentence[index : index + maximum] for index in range(0, len(sentence), maximum))
            continue
        candidate = f"{current} {sentence}".strip()
        if current and len(candidate) > maximum and len(current) >= minimum:
            blocks.append(current)
            current = sentence
        else:
            current = candidate
    if current:
        if blocks and len(current) < minimum and len(blocks[-1]) + 1 + len(current) <= maximum:
            blocks[-1] = f"{blocks[-1]} {current}"
        else:
            blocks.append(current)
    return blocks

from __future__ import annotations

from dataclasses import asdict, dataclass
from typing import Any

from muclegal.normalize.core import normalize_plain_text


CLASSIFICATIONS = {"beseitigt", "kerngleich", "neuer_sachverhalt", "unsicher"}
CONFIDENCE_LEVELS = {"hoch", "mittel", "niedrig"}
REQUIRED_FIELDS = {
    "classification",
    "tenor_element_id",
    "confidence",
    "evidence_quote",
    "reasoning",
}


@dataclass(frozen=True)
class ClauseClassification:
    classification: str
    tenor_element_id: str | None
    confidence: str
    evidence_quote: str | None
    reasoning: str
    validation_error: str | None = None

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


def validate_clause_classification(
    value: Any,
    tenor_elements: list[dict[str, Any]],
    old_clause: str | None,
    new_clause: str | None,
) -> ClauseClassification:
    """Validate a model result and fail closed to the first-class `unsicher` result."""
    error = _validation_error(value, tenor_elements, old_clause, new_clause)
    if error:
        return ClauseClassification(
            classification="unsicher",
            tenor_element_id=None,
            confidence="niedrig",
            evidence_quote=None,
            reasoning=f"Automatische Validierung fehlgeschlagen: {error}",
            validation_error=error,
        )
    return ClauseClassification(
        classification=value["classification"],
        tenor_element_id=value["tenor_element_id"],
        confidence=value["confidence"],
        evidence_quote=value["evidence_quote"],
        reasoning=value["reasoning"].strip(),
    )


def _validation_error(
    value: Any,
    tenor_elements: list[dict[str, Any]],
    old_clause: str | None,
    new_clause: str | None,
) -> str | None:
    if not isinstance(value, dict) or set(value) != REQUIRED_FIELDS:
        return "Antwort entspricht nicht dem Klassifikationsschema."
    if value["classification"] not in CLASSIFICATIONS:
        return "Unzulässige Klassifikation."
    if value["confidence"] not in CONFIDENCE_LEVELS:
        return "Unzulässige Konfidenz."
    if not isinstance(value["reasoning"], str) or not value["reasoning"].strip():
        return "Begründung fehlt."
    element_ids = {
        item.get("id") for item in tenor_elements if isinstance(item, dict) and item.get("id")
    }
    if value["tenor_element_id"] not in element_ids:
        return "Tenor-Element existiert nicht."
    quote = value["evidence_quote"]
    if not isinstance(quote, str) or not quote.strip():
        return "Wörtliches Belegzitat fehlt."
    normalized_quote = normalize_plain_text(quote).strip()
    sources = [normalize_plain_text(item).strip() for item in (old_clause, new_clause) if item]
    if not normalized_quote or not any(normalized_quote in source for source in sources):
        return "Belegzitat kommt im alten oder neuen Klauseltext nicht wörtlich vor."
    return None

from __future__ import annotations

from dataclasses import dataclass
from difflib import SequenceMatcher

from muclegal.normalize.clauses import Clause


@dataclass(frozen=True)
class ClausePair:
    previous: Clause | None
    current: Clause | None
    similarity: float


def pair_clause_changes(
    previous: tuple[Clause, ...], current: tuple[Clause, ...]
) -> tuple[ClausePair, ...]:
    """Pair changed clauses structurally, then by text similarity; omit unchanged hashes."""
    current_hashes = {clause.clause_hash for clause in current}
    previous_hashes = {clause.clause_hash for clause in previous}
    removed = [clause for clause in previous if clause.clause_hash not in current_hashes]
    added = [clause for clause in current if clause.clause_hash not in previous_hashes]
    available = set(range(len(added)))
    pairs: list[ClausePair] = []

    for old in removed:
        ranked: list[tuple[float, float, int]] = []
        for index in available:
            new = added[index]
            similarity = SequenceMatcher(None, old.text, new.text).ratio()
            same_heading = bool(old.heading_path and old.heading_path == new.heading_path)
            ordinal_proximity = 1 / (1 + abs(old.ordinal - new.ordinal))
            score = similarity + (0.5 if same_heading else 0.0) + 0.1 * ordinal_proximity
            ranked.append((score, similarity, index))
        if not ranked:
            pairs.append(ClausePair(old, None, 0.0))
            continue
        _, similarity, best_index = max(ranked)
        best = added[best_index]
        structurally_same = (
            old.heading_path == best.heading_path and abs(old.ordinal - best.ordinal) <= 1
        )
        if similarity > 0.5 or structurally_same:
            available.remove(best_index)
            pairs.append(ClausePair(old, best, similarity))
        else:
            pairs.append(ClausePair(old, None, similarity))

    pairs.extend(ClausePair(None, added[index], 0.0) for index in sorted(available))
    return tuple(
        sorted(
            pairs,
            key=lambda pair: (
                pair.current.ordinal if pair.current else pair.previous.ordinal,
                pair.current is None,
            ),
        )
    )

